class A {
    int f(Object o) {
        return switch (o) {
            case String s when s.isEmpty() -> 0;
            case Integer i -> i;
            case null, default -> -1;
        };
    }
}

class A {
    int f(Object o) {
        switch (o) {
            case null -> {}
            default -> {}
        }
        switch (o) {
            case null:
            default:
                break;
        }
        return switch (o) {
            case null, default -> 1;
        };
    }
}

class A {
    int f(Object o, int when) {
        int yield = switch (o) {
            case String record when when > 0 -> record.length();
            case null, default -> when;
        };
        return yield;
    }
}

